-- Air Cargo Flights benchmark -- MIXED schema (generated by scripts/build_variants.py from schema/schema.sql; do not edit)
PRAGMA foreign_keys = ON;

CREATE TABLE bm_param (
    param_schl TEXT PRIMARY KEY,
    param_wert TEXT NOT NULL
);

CREATE TABLE flghf (
    fh_nr            INTEGER PRIMARY KEY,
    iata_cd          TEXT NOT NULL UNIQUE CHECK (length(iata_cd) = 3),
    icao_cd          TEXT NOT NULL UNIQUE CHECK (length(icao_cd) = 4),
    bez              TEXT NOT NULL,
    ort              TEXT NOT NULL,
    land             TEXT NOT NULL,
    reg              TEXT NOT NULL CHECK (reg IN ('north_america', 'europe', 'middle_east', 'asia_pacific')),
    zeitz            TEXT NOT NULL,
    breite           REAL NOT NULL CHECK (breite  BETWEEN  -90 AND  90),
    laenge           REAL NOT NULL CHECK (laenge BETWEEN -180 AND 180),
    hoehe_m          INTEGER NOT NULL,
    anz_slb          INTEGER NOT NULL CHECK (anz_slb >= 1),
    max_slb_m        INTEGER NOT NULL CHECK (max_slb_m > 0),
    hub_kz           INTEGER NOT NULL DEFAULT 0 CHECK (hub_kz IN (0, 1)),
    kap_jahr_t       INTEGER NOT NULL CHECK (kap_jahr_t > 0),
    zoll_24h_kz      INTEGER NOT NULL CHECK (zoll_24h_kz IN (0, 1)),
    nachtflugverb_kz INTEGER NOT NULL CHECK (nachtflugverb_kz IN (0, 1))
);

CREATE TABLE flges (
    flges_nr      INTEGER PRIMARY KEY,
    iata_cd       TEXT NOT NULL UNIQUE CHECK (length(iata_cd) = 2),
    icao_cd       TEXT NOT NULL UNIQUE CHECK (length(icao_cd) = 3),
    bez           TEXT NOT NULL UNIQUE,
    rufz          TEXT NOT NULL UNIQUE,
    land          TEXT NOT NULL,
    sitz_ort      TEXT NOT NULL,
    gruend_jahr   INTEGER NOT NULL CHECK (gruend_jahr BETWEEN 1900 AND 2025),
    hub_fh_nr     INTEGER NOT NULL REFERENCES flghf(fh_nr),
    allianz       TEXT CHECK (allianz IS NULL OR allianz IN ('CargoLink', 'SkyFreight Alliance')),
    nur_fracht_kz INTEGER NOT NULL CHECK (nur_fracht_kz IN (0, 1)),
    aoc_nr        TEXT NOT NULL UNIQUE,
    web_adr       TEXT NOT NULL,
    kontakt_mail  TEXT NOT NULL
);

CREATE TABLE lfz_typ (
    typ_nr           INTEGER PRIMARY KEY,
    mdl              TEXT NOT NULL UNIQUE,
    icao_typ         TEXT NOT NULL UNIQUE,
    herst            TEXT NOT NULL,
    anz_trw          INTEGER NOT NULL CHECK (anz_trw IN (2, 4)),
    trw_mdl          TEXT NOT NULL,
    max_nutzl_kg     INTEGER NOT NULL CHECK (max_nutzl_kg > 0),
    max_vol_m3       REAL    NOT NULL CHECK (max_vol_m3 > 0),
    max_reichw_km    INTEGER NOT NULL CHECK (max_reichw_km > 0),
    reise_geschw_kmh INTEGER NOT NULL CHECK (reise_geschw_kmh > 0),
    mtow_kg          INTEGER NOT NULL CHECK (mtow_kg > 0),
    leergew_kg       INTEGER NOT NULL CHECK (leergew_kg > 0),
    tank_kap_kg      INTEGER NOT NULL CHECK (tank_kap_kg > 0),
    verbr_kg_h       INTEGER NOT NULL CHECK (verbr_kg_h > 0),
    anz_hd_pos       INTEGER NOT NULL CHECK (anz_hd_pos > 0),
    spannw_m         REAL    NOT NULL CHECK (spannw_m > 0),
    CHECK (leergew_kg + max_nutzl_kg <= mtow_kg)
);

CREATE TABLE lfz (
    lfz_nr          INTEGER PRIMARY KEY,
    kennz           TEXT NOT NULL UNIQUE,
    msn             TEXT NOT NULL UNIQUE,
    typ_nr          INTEGER NOT NULL REFERENCES lfz_typ(typ_nr),
    flges_nr        INTEGER NOT NULL REFERENCES flges(flges_nr),
    heimat_fh_nr    INTEGER NOT NULL REFERENCES flghf(fh_nr),
    zul_land        TEXT NOT NULL,
    baujahr         INTEGER NOT NULL CHECK (baujahr BETWEEN 1990 AND 2025),
    ausl_dat        TEXT NOT NULL,
    eigt_art        TEXT NOT NULL CHECK (eigt_art IN ('owned', 'leased')),
    leasgeb         TEXT,
    leas_ende_dat   TEXT,
    ges_flugstd     INTEGER NOT NULL CHECK (ges_flugstd >= 0),
    ges_zyklen      INTEGER NOT NULL CHECK (ges_zyklen >= 0),
    letzt_c_chk_dat TEXT,
    stat            TEXT NOT NULL CHECK (stat IN ('active', 'maintenance', 'retired')),
    CHECK ((eigt_art = 'leased') = (leasgeb IS NOT NULL AND leas_ende_dat IS NOT NULL)),
    CHECK (CAST(substr(ausl_dat, 1, 4) AS INTEGER) >= baujahr)
);

CREATE TABLE knd_stamm (
    kunnr            INTEGER PRIMARY KEY,
    kto_cd           TEXT NOT NULL UNIQUE,
    name1            TEXT NOT NULL,
    knd_typ          TEXT NOT NULL CHECK (knd_typ IN ('shipper', 'freight_forwarder', 'retailer', 'manufacturer')),
    land             TEXT NOT NULL,
    ort              TEXT NOT NULL,
    strasse          TEXT NOT NULL,
    plz              TEXT NOT NULL,
    ansprechp        TEXT NOT NULL,
    ansp_mail        TEXT NOT NULL,
    ansp_tel         TEXT NOT NULL,
    web_adr          TEXT,
    vertr_reg        TEXT NOT NULL CHECK (vertr_reg IN ('north_america', 'south_america', 'europe', 'middle_east', 'asia_pacific')),
    kredlim_usd      REAL NOT NULL CHECK (kredlim_usd > 0),
    zahlbed_tg       INTEGER NOT NULL CHECK (zahlbed_tg IN (15, 30, 45, 60)),
    bek_versender_kz INTEGER NOT NULL CHECK (bek_versender_kz IN (0, 1)),
    treue_stufe      TEXT NOT NULL CHECK (treue_stufe IN ('bronze', 'silver', 'gold', 'platinum')),
    erdat            TEXT NOT NULL,
    UNIQUE (name1, land)
);

CREATE TABLE lgr (
    lgr_nr        INTEGER PRIMARY KEY,
    lgr_cd        TEXT NOT NULL UNIQUE,
    fh_nr         INTEGER NOT NULL REFERENCES flghf(fh_nr),
    betreiber     TEXT NOT NULL,
    lgr_typ       TEXT NOT NULL CHECK (lgr_typ IN ('general', 'cold_chain', 'dangerous_goods', 'express')),
    flaeche_m2    INTEGER NOT NULL CHECK (flaeche_m2 > 0),
    kap_t         INTEGER NOT NULL CHECK (kap_t > 0),
    anz_kuehlr    INTEGER NOT NULL CHECK (anz_kuehlr >= 0),
    min_temp_c    REAL,
    anz_tore      INTEGER NOT NULL CHECK (anz_tore > 0),
    gefgut_ber_kz INTEGER NOT NULL CHECK (gefgut_ber_kz IN (0, 1)),
    zolllager_kz  INTEGER NOT NULL CHECK (zolllager_kz IN (0, 1)),
    sich_stufe    TEXT NOT NULL CHECK (sich_stufe IN ('standard', 'high')),
    betr_24h_kz   INTEGER NOT NULL CHECK (betr_24h_kz IN (0, 1)),
    eroeff_jahr   INTEGER NOT NULL CHECK (eroeff_jahr BETWEEN 1950 AND 2025),
    miete_mon_usd REAL NOT NULL CHECK (miete_mon_usd > 0),
    CHECK ((anz_kuehlr = 0) = (min_temp_c IS NULL)),
    CHECK (lgr_typ <> 'cold_chain' OR anz_kuehlr > 0),
    CHECK (lgr_typ <> 'dangerous_goods' OR gefgut_ber_kz = 1)
);

CREATE TABLE bes_mitgl (
    pers_nr        INTEGER PRIMARY KEY,
    ma_nr          TEXT NOT NULL UNIQUE,
    vorname        TEXT NOT NULL,
    nachname       TEXT NOT NULL,
    mail           TEXT NOT NULL UNIQUE,
    flges_nr       INTEGER NOT NULL REFERENCES flges(flges_nr),
    basis_fh       INTEGER NOT NULL REFERENCES flghf(fh_nr),
    dienstgrad     TEXT NOT NULL CHECK (dienstgrad IN ('captain', 'first_officer', 'loadmaster')),
    musterber_typ  INTEGER REFERENCES lfz_typ(typ_nr),
    lizenz_nr      TEXT UNIQUE,
    lizenz_ablauf  TEXT,
    med_ablauf     TEXT,
    eintr_dat      TEXT NOT NULL,
    dienstalter_nr INTEGER NOT NULL CHECK (dienstalter_nr >= 1),
    ges_flugstd    INTEGER NOT NULL CHECK (ges_flugstd >= 0),
    aktiv_kz       INTEGER NOT NULL CHECK (aktiv_kz IN (0, 1)),
    UNIQUE (flges_nr, dienstalter_nr),
    CHECK ((dienstgrad = 'loadmaster') = (musterber_typ IS NULL)),
    CHECK ((dienstgrad = 'loadmaster') = (lizenz_nr IS NULL AND lizenz_ablauf IS NULL AND med_ablauf IS NULL))
);

CREATE TABLE flug (
    flug_id           INTEGER PRIMARY KEY,
    flugnr            TEXT NOT NULL,
    flug_art          TEXT NOT NULL CHECK (flug_art IN ('scheduled', 'charter')),
    lfz_nr            INTEGER NOT NULL REFERENCES lfz(lfz_nr),
    abfl_fh           INTEGER NOT NULL REFERENCES flghf(fh_nr),
    ziel_fh           INTEGER NOT NULL REFERENCES flghf(fh_nr),
    abfl_plan         TEXT NOT NULL,
    ank_plan          TEXT NOT NULL,
    abfl_ist          TEXT,
    ank_ist           TEXT,
    abfl_pos          TEXT NOT NULL,
    ank_pos           TEXT NOT NULL,
    entf_km           INTEGER NOT NULL CHECK (entf_km > 0),
    reiseflughoehe_ft INTEGER NOT NULL CHECK (reiseflughoehe_ft BETWEEN 20000 AND 43000),
    tow_kg            INTEGER,
    wetter_abfl       TEXT CHECK (wetter_abfl IS NULL OR wetter_abfl IN
                                   ('clear', 'cloudy', 'rain', 'snow', 'fog', 'thunderstorm')),
    versp_cd          TEXT,
    storno_grund      TEXT CHECK (storno_grund IS NULL OR storno_grund IN
                                   ('weather', 'technical', 'crew', 'commercial', 'atc')),
    stat              TEXT NOT NULL CHECK (stat IN ('scheduled', 'completed', 'cancelled')),
    UNIQUE (flugnr, abfl_plan),
    CHECK (abfl_fh <> ziel_fh),
    CHECK (ank_plan > abfl_plan),
    CHECK (
        (stat = 'completed' AND abfl_ist IS NOT NULL AND ank_ist IS NOT NULL
                              AND ank_ist > abfl_ist)
     OR (stat <> 'completed' AND abfl_ist IS NULL AND ank_ist IS NULL)
    ),
    CHECK ((stat = 'completed') = (tow_kg IS NOT NULL)),
    CHECK ((stat = 'cancelled') = (storno_grund IS NOT NULL)),
    CHECK ((stat = 'scheduled') = (wetter_abfl IS NULL)),
    CHECK (versp_cd IS NULL OR stat = 'completed')
);

CREATE TABLE bes_eins (
    eins_id      INTEGER PRIMARY KEY,
    flug_id      INTEGER NOT NULL REFERENCES flug(flug_id),
    pers_nr      INTEGER NOT NULL REFERENCES bes_mitgl(pers_nr),
    funktion     TEXT NOT NULL CHECK (funktion IN ('captain', 'first_officer', 'relief_pilot', 'loadmaster')),
    pf_kz        INTEGER NOT NULL CHECK (pf_kz IN (0, 1)),
    meld_zeit    TEXT NOT NULL,
    ende_zeit    TEXT NOT NULL,
    block_min    INTEGER,
    ruhe_min_vor INTEGER,
    spesen_usd   REAL NOT NULL CHECK (spesen_usd >= 0),
    hotel_kz     INTEGER NOT NULL CHECK (hotel_kz IN (0, 1)),
    eins_stat    TEXT NOT NULL CHECK (eins_stat IN ('rostered', 'completed')),
    UNIQUE (flug_id, pers_nr),
    CHECK (ende_zeit > meld_zeit),
    CHECK (pf_kz = 0 OR funktion IN ('captain', 'first_officer')),
    CHECK ((eins_stat = 'completed') = (block_min IS NOT NULL))
);

CREATE TABLE wartg (
    wartg_id        INTEGER PRIMARY KEY,
    auftr_nr        TEXT NOT NULL UNIQUE,
    lfz_nr          INTEGER NOT NULL REFERENCES lfz(lfz_nr),
    fh_nr           INTEGER NOT NULL REFERENCES flghf(fh_nr),
    chk_art         TEXT NOT NULL CHECK (chk_art IN ('line', 'A_check', 'B_check', 'C_check', 'unscheduled')),
    ata_kap         INTEGER CHECK (ata_kap IS NULL OR ata_kap BETWEEN 5 AND 80),
    mro_dienstl     TEXT NOT NULL,
    beginn          TEXT NOT NULL,
    ende            TEXT,
    arb_std         REAL,
    teile_kost_usd  REAL CHECK (teile_kost_usd IS NULL OR teile_kost_usd >= 0),
    lohn_kost_usd   REAL CHECK (lohn_kost_usd IS NULL OR lohn_kost_usd >= 0),
    anz_zurueckgest INTEGER NOT NULL CHECK (anz_zurueckgest >= 0),
    aog_kz          INTEGER NOT NULL CHECK (aog_kz IN (0, 1)),
    naechst_faell   TEXT,
    stat            TEXT NOT NULL CHECK (stat IN ('planned', 'in_progress', 'completed')),
    CHECK (ende IS NULL OR ende > beginn),
    CHECK ((stat = 'in_progress') = (ende IS NULL)),
    CHECK ((stat = 'completed') = (arb_std IS NOT NULL AND teile_kost_usd IS NOT NULL AND lohn_kost_usd IS NOT NULL)),
    CHECK ((chk_art = 'unscheduled') = (ata_kap IS NOT NULL)),
    CHECK (aog_kz = 0 OR chk_art = 'unscheduled')
);

CREATE TABLE betankg (
    betank_id    INTEGER PRIMARY KEY,
    beleg_nr     TEXT NOT NULL UNIQUE,
    flug_id      INTEGER NOT NULL UNIQUE REFERENCES flug(flug_id),
    fh_nr        INTEGER NOT NULL REFERENCES flghf(fh_nr),
    lieferant    TEXT NOT NULL,
    krst_art     TEXT NOT NULL CHECK (krst_art IN ('Jet A', 'Jet A-1')),
    liefer_art   TEXT NOT NULL CHECK (liefer_art IN ('hydrant', 'truck')),
    betank_zeit  TEXT NOT NULL,
    menge_kg     INTEGER NOT NULL CHECK (menge_kg > 0),
    menge_l      INTEGER NOT NULL CHECK (menge_l > 0),
    dichte       REAL NOT NULL CHECK (dichte BETWEEN 0.775 AND 0.840),
    preis_usd_l  REAL NOT NULL CHECK (preis_usd_l > 0),
    ges_kost_usd REAL NOT NULL CHECK (ges_kost_usd > 0),
    saf_ant_pct  REAL NOT NULL CHECK (saf_ant_pct BETWEEN 0 AND 50),
    verbr_kg     INTEGER NOT NULL CHECK (verbr_kg > 0),
    co2_kg       INTEGER NOT NULL CHECK (co2_kg > 0),
    CHECK (verbr_kg <= menge_kg)
);

CREATE TABLE sndg (
    sndg_nr         INTEGER PRIMARY KEY,
    lbf_nr          TEXT NOT NULL UNIQUE,
    kunnr           INTEGER NOT NULL REFERENCES knd_stamm(kunnr),
    knd_ref         TEXT,
    empf_name       TEXT NOT NULL,
    urspr_fh        INTEGER NOT NULL REFERENCES flghf(fh_nr),
    ziel_fh         INTEGER NOT NULL REFERENCES flghf(fh_nr),
    buch_dat        TEXT NOT NULL,
    wunsch_lief_dat TEXT NOT NULL,
    serv_lvl        TEXT NOT NULL CHECK (serv_lvl IN ('express', 'standard', 'economy')),
    waren_kat       TEXT NOT NULL CHECK (waren_kat IN
        ('electronics', 'pharmaceuticals', 'perishables', 'automotive_parts', 'apparel', 'machinery', 'documents')),
    anz_stk         INTEGER NOT NULL CHECK (anz_stk > 0),
    ges_gew_kg      REAL NOT NULL CHECK (ges_gew_kg > 0),
    ges_vol_m3      REAL NOT NULL CHECK (ges_vol_m3 > 0),
    fracht_gew_kg   REAL NOT NULL,
    dekl_wert_usd   REAL NOT NULL CHECK (dekl_wert_usd >= 0),
    gefgut_kz       INTEGER NOT NULL CHECK (gefgut_kz IN (0, 1)),
    gefgut_kl       TEXT CHECK (gefgut_kl IS NULL OR gefgut_kl IN ('2.2', '3', '8', '9')),
    temp_kz         INTEGER NOT NULL CHECK (temp_kz IN (0, 1)),
    temp_min_c      REAL,
    temp_max_c      REAL,
    stat            TEXT NOT NULL CHECK (stat IN ('booked', 'in_transit', 'delivered', 'cancelled')),
    CHECK (urspr_fh <> ziel_fh),
    CHECK (wunsch_lief_dat > buch_dat),
    CHECK (fracht_gew_kg >= ges_gew_kg),
    CHECK ((gefgut_kz = 1) = (gefgut_kl IS NOT NULL)),
    CHECK ((temp_kz = 1) = (temp_min_c IS NOT NULL AND temp_max_c IS NOT NULL)),
    CHECK (temp_min_c IS NULL OR temp_min_c < temp_max_c)
);

CREATE TABLE flug_ladg (
    ladg_id     INTEGER PRIMARY KEY,
    sndg_nr     INTEGER NOT NULL REFERENCES sndg(sndg_nr),
    flug_id     INTEGER NOT NULL REFERENCES flug(flug_id),
    abschn_nr   INTEGER NOT NULL CHECK (abschn_nr >= 1),
    uld_typ     TEXT NOT NULL CHECK (uld_typ IN ('PMC', 'PAG', 'AKE', 'RKN', 'BULK')),
    uld_nr      TEXT,
    deck_cd     TEXT NOT NULL CHECK (deck_cd IN ('main', 'lower')),
    pos_cd      TEXT NOT NULL,
    lade_folge  INTEGER NOT NULL CHECK (lade_folge >= 1),
    plomben_nr  TEXT,
    geladen_um  TEXT,
    abschn_stat TEXT NOT NULL CHECK (abschn_stat IN ('planned', 'flown')),
    UNIQUE (sndg_nr, abschn_nr),
    UNIQUE (sndg_nr, flug_id),
    UNIQUE (flug_id, lade_folge),
    CHECK ((uld_typ = 'BULK') = (uld_nr IS NULL)),
    CHECK ((uld_typ IN ('PMC', 'PAG')) = (deck_cd = 'main')),
    CHECK ((abschn_stat = 'flown') = (geladen_um IS NOT NULL))
);

CREATE TABLE rech_kopf (
    rech_id            INTEGER PRIMARY KEY,
    belnr              TEXT NOT NULL UNIQUE,
    sndg_nr            INTEGER NOT NULL UNIQUE REFERENCES sndg(sndg_nr),
    ausst_dat          TEXT NOT NULL,
    faell_dat          TEXT NOT NULL,
    zahlbed_tg         INTEGER NOT NULL CHECK (zahlbed_tg IN (15, 30, 45, 60)),
    fracht_usd         REAL NOT NULL CHECK (fracht_usd > 0),
    treibst_zuschl_usd REAL NOT NULL CHECK (treibst_zuschl_usd >= 0),
    sich_geb_usd       REAL NOT NULL CHECK (sich_geb_usd >= 0),
    abfert_geb_usd     REAL NOT NULL CHECK (abfert_geb_usd >= 0),
    gefgut_zuschl_usd  REAL NOT NULL CHECK (gefgut_zuschl_usd >= 0),
    rabatt_usd         REAL NOT NULL CHECK (rabatt_usd >= 0),
    brutto_usd         REAL NOT NULL CHECK (brutto_usd > 0),
    versand_weg        TEXT NOT NULL CHECK (versand_weg IN ('email', 'portal', 'edi')),
    stat               TEXT NOT NULL CHECK (stat IN ('unpaid', 'partially_paid', 'paid')),
    CHECK (faell_dat >= ausst_dat)
);

CREATE TABLE zahlg (
    zahlg_id      INTEGER PRIMARY KEY,
    zahl_ref      TEXT NOT NULL UNIQUE,
    rech_id       INTEGER NOT NULL REFERENCES rech_kopf(rech_id),
    kunnr         INTEGER NOT NULL REFERENCES knd_stamm(kunnr),
    zahl_dat      TEXT NOT NULL,
    betr_usd      REAL NOT NULL CHECK (betr_usd > 0),
    orig_waehr    TEXT NOT NULL CHECK (length(orig_waehr) = 3),
    orig_betr     REAL NOT NULL CHECK (orig_betr > 0),
    wkurs_usd     REAL NOT NULL CHECK (wkurs_usd > 0),
    zahl_art      TEXT NOT NULL CHECK (zahl_art IN ('wire_transfer', 'ach', 'credit_card')),
    bankgeb_usd   REAL NOT NULL CHECK (bankgeb_usd >= 0),
    abgestimmt_kz INTEGER NOT NULL CHECK (abgestimmt_kz IN (0, 1)),
    CHECK (orig_waehr <> 'USD' OR wkurs_usd = 1)
);

CREATE TABLE vorf (
    vorf_id       INTEGER PRIMARY KEY,
    ladg_id       INTEGER NOT NULL REFERENCES flug_ladg(ladg_id),
    fh_nr         INTEGER NOT NULL REFERENCES flghf(fh_nr),
    lgr_nr        INTEGER REFERENCES lgr(lgr_nr),
    vorf_art      TEXT NOT NULL CHECK (vorf_art IN
        ('damage', 'delay', 'missing_documents', 'temperature_excursion', 'loss')),
    schwere       TEXT NOT NULL CHECK (schwere IN ('low', 'medium', 'high')),
    ursache       TEXT NOT NULL CHECK (ursache IN ('handling', 'packaging', 'weather', 'documentation', 'equipment', 'unknown')),
    gemeldet_von  TEXT NOT NULL CHECK (gemeldet_von IN ('ground_handler', 'crew', 'customer', 'customs')),
    meld_zeit     TEXT NOT NULL,
    betr_stk      INTEGER CHECK (betr_stk IS NULL OR betr_stk >= 1),
    versp_min     INTEGER CHECK (versp_min IS NULL OR versp_min > 0),
    ford_betr_usd REAL CHECK (ford_betr_usd IS NULL OR ford_betr_usd >= 0),
    korr_massn    TEXT CHECK (korr_massn IS NULL OR korr_massn IN
        ('repacked', 'rerouted', 'compensated', 'documents_supplied', 'no_action')),
    erledigt_kz   INTEGER NOT NULL CHECK (erledigt_kz IN (0, 1)),
    erledigt_am   TEXT,
    CHECK ((erledigt_kz = 1) = (erledigt_am IS NOT NULL)),
    CHECK ((erledigt_kz = 1) = (korr_massn IS NOT NULL)),
    CHECK (erledigt_am IS NULL OR erledigt_am > meld_zeit),
    CHECK ((vorf_art = 'delay') = (versp_min IS NOT NULL))
);

CREATE TABLE vers_schad (
    schad_id      INTEGER PRIMARY KEY,
    schad_nr      TEXT NOT NULL UNIQUE,
    vorf_id       INTEGER NOT NULL UNIQUE REFERENCES vorf(vorf_id),
    kunnr         INTEGER NOT NULL REFERENCES knd_stamm(kunnr),
    police_nr     TEXT NOT NULL,
    versicherer   TEXT NOT NULL,
    deckung_art   TEXT NOT NULL CHECK (deckung_art IN ('all_risk', 'named_perils')),
    meld_dat      TEXT NOT NULL,
    ford_usd      REAL NOT NULL CHECK (ford_usd >= 0),
    selbstbeh_usd REAL NOT NULL CHECK (selbstbeh_usd >= 0),
    genehm_usd    REAL CHECK (genehm_usd IS NULL OR genehm_usd >= 0),
    stat          TEXT NOT NULL CHECK (stat IN ('filed', 'under_review', 'approved', 'rejected', 'paid')),
    entsch_dat    TEXT,
    ablehn_grund  TEXT CHECK (ablehn_grund IS NULL OR ablehn_grund IN
        ('inadequate_packaging', 'late_notification', 'excluded_cause', 'insufficient_documentation')),
    reg_dat       TEXT,
    sachbearb     TEXT NOT NULL,
    CHECK ((stat IN ('approved', 'paid')) = (genehm_usd IS NOT NULL)),
    CHECK ((stat IN ('approved', 'rejected', 'paid')) = (entsch_dat IS NOT NULL)),
    CHECK ((stat = 'rejected') = (ablehn_grund IS NOT NULL)),
    CHECK ((stat = 'paid') = (reg_dat IS NOT NULL)),
    CHECK (genehm_usd IS NULL OR genehm_usd <= ford_usd)
);

CREATE TABLE zoll_anm (
    anm_id        INTEGER PRIMARY KEY,
    anm_nr        TEXT NOT NULL UNIQUE,
    sndg_nr       INTEGER NOT NULL REFERENCES sndg(sndg_nr),
    lgr_nr        INTEGER NOT NULL REFERENCES lgr(lgr_nr),
    anm_art       TEXT NOT NULL CHECK (anm_art IN ('export', 'import')),
    zoll_land     TEXT NOT NULL,
    zolltarif_nr  TEXT NOT NULL CHECK (length(zolltarif_nr) = 6),
    waren_bez     TEXT NOT NULL,
    zollwert_usd  REAL NOT NULL CHECK (zollwert_usd >= 0),
    zollsatz_pct  REAL NOT NULL CHECK (zollsatz_pct >= 0),
    zoll_betr_usd REAL NOT NULL CHECK (zoll_betr_usd >= 0),
    eust_usd      REAL NOT NULL CHECK (eust_usd >= 0),
    zollagent     TEXT NOT NULL,
    beschau_kz    INTEGER NOT NULL CHECK (beschau_kz IN (0, 1)),
    beschau_erg   TEXT CHECK (beschau_erg IS NULL OR beschau_erg IN ('passed', 'discrepancy')),
    eingereicht   TEXT NOT NULL,
    freigabe      TEXT,
    stat          TEXT NOT NULL CHECK (stat IN ('pending', 'cleared', 'held')),
    UNIQUE (sndg_nr, anm_art),
    CHECK ((stat = 'cleared') = (freigabe IS NOT NULL)),
    CHECK (freigabe IS NULL OR freigabe > eingereicht),
    CHECK (beschau_erg IS NULL OR beschau_kz = 1),
    CHECK (stat <> 'held' OR beschau_erg = 'discrepancy'),
    CHECK (anm_art = 'import' OR (zoll_betr_usd = 0 AND eust_usd = 0))
);

CREATE TABLE sdg_verfolg (
    ereig_id    INTEGER PRIMARY KEY,
    sndg_nr     INTEGER NOT NULL REFERENCES sndg(sndg_nr),
    flug_id     INTEGER REFERENCES flug(flug_id),
    fh_nr       INTEGER NOT NULL REFERENCES flghf(fh_nr),
    lgr_nr      INTEGER REFERENCES lgr(lgr_nr),
    ereig_cd    TEXT NOT NULL CHECK (ereig_cd IN ('BKD', 'RCS', 'DEP', 'ARR', 'RCF', 'NFD', 'DLV', 'CAN')),
    ereig_zeit  TEXT NOT NULL,
    anz_stk     INTEGER NOT NULL CHECK (anz_stk >= 0),
    gew_kg      REAL,
    temp_c      REAL,
    erfasst_von TEXT NOT NULL CHECK (erfasst_von IN ('system', 'ground_handler', 'customer_portal')),
    scanner_nr  TEXT,
    CHECK ((ereig_cd IN ('DEP', 'ARR')) = (flug_id IS NOT NULL)),
    CHECK ((ereig_cd IN ('RCS', 'RCF', 'NFD', 'DLV')) = (lgr_nr IS NOT NULL)),
    CHECK ((erfasst_von = 'ground_handler') = (scanner_nr IS NOT NULL)),
    CHECK (gew_kg IS NULL OR ereig_cd = 'RCS')
);

CREATE INDEX ix_lfz_1 ON lfz(typ_nr);
CREATE INDEX ix_flug_1 ON flug(lfz_nr, abfl_plan);
CREATE INDEX ix_flug_2 ON flug(abfl_fh, ziel_fh);
